-- Hellfire Peninsula combat abilities
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (16590,16846,16901,16904,16905,16906,17035,17053,17057,17058,19188,19190,19191,19264,19349,19457);
